<?php

declare(strict_types=1);

namespace App\Http\Controllers;

use App\Models\PostMedia;
use App\Models\User;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Storage;

/**
 * @group Media
 *
 * Download signed media files for posts and avatars.
 *
 * @authenticated
 */
class MediaController extends Controller
{
    /**
     * Download a post media file.
     *
     * Requires the original signed URL query string generated by the API.
     *
     * @urlParam postMedia integer required The post media ID. Example: 1
     *
     * @queryParam poster boolean Return the generated video poster image instead of the media file. Example: false
     *
     * @response 200 Binary file download
     * @response 403 {"message":"Invalid signature."}
     * @response 404 {"message":"Not Found"}
     */
    public function showPostMedia(Request $request, PostMedia $postMedia)
    {
        abort_unless($request->hasValidSignature(), 403);
        abort_unless($postMedia->status === 'ready', 404);

        $this->authorize('can_view_post', $postMedia->post);

        $path = $request->boolean('poster') ? $postMedia->poster_path : $postMedia->path;
        abort_unless($path, 404);

        return Storage::disk($postMedia->disk)->download($path);
    }

    /**
     * Download a user's avatar.
     *
     * Requires the original signed URL query string generated by the API.
     *
     * @urlParam user integer required The user ID. Example: 1
     *
     * @response 200 Binary file download
     * @response 403 {"message":"Invalid signature."}
     * @response 404 {"message":"Not Found"}
     */
    public function showAvatar(Request $request, User $user)
    {
        abort_unless($request->hasValidSignature(), 403);
        abort_unless($user->avatar, 404);

        $this->authorize('can_view_profile', $user);

        return Storage::disk($user->avatar_disk ?: config('media.disk'))->download($user->avatar);
    }
}
